{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Zalcitabine (ddC), a 2',3'-dideoxycytidine sharing the cytosine base and deoxyribose-like scaffold with the query, has approximately 70–90% oral bioavailability in patients, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Lamivudine, a cytidine analog with a modified sugar, shows absolute oral bioavailability of 95 ± 5% in HIV patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Mericitabine, a cytidine nucleoside prodrug, has excellent oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Doxifluridine, a pyrimidine deoxyribonucleoside, has oral bioavailability of 34–47% in humans, above the 20% threshold, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "MK-8591, a nucleoside analog, is characterized by high oral bioavailability in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple close nucleoside analogues with very high assay-transfer scores show oral bioavailability well above 20%, including cytidine/deoxycytidine analogs with measured F values of 70–100%. The query's polar physicochemical prior is unfavorable for passive permeability, but the strong experimental evidence from structurally related nucleosides, likely absorbed via nucleoside transporters, supports a high oral bioavailability prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for 2'-deoxycytidine itself is provided.",
    "Potential metabolic lability via cytidine deaminase or first-pass metabolism is not directly captured by the analogue evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

